<?php
namespace App\Services;use App\Models\{AdvancePayment,AttendanceMonth,AttendanceRecord,ExtraDuty,ImportLog};use Carbon\Carbon;use PhpOffice\PhpSpreadsheet\IOFactory;use PhpOffice\PhpSpreadsheet\Cell\Coordinate;use Illuminate\Support\Facades\DB;
class ExcelImportService{public function __construct(public EmployeeMatchService $m){} public function import(?string $advance,?string $timesheet,string $project,int $month,int $year,?int $uid=null):array{$s=['advance'=>['total'=>0,'success'=>0,'failed'=>0],'timesheet'=>['total'=>0,'success'=>0,'failed'=>0]];if($advance&&file_exists($advance))$s['advance']=$this->advance($advance,$uid);if($timesheet&&file_exists($timesheet))$s['timesheet']=$this->timesheet($timesheet,$project,$month,$year,$uid);return $s;}
function val($sh,$r,$c){return $c?trim((string)$sh->getCellByColumnAndRow($c,$r)->getCalculatedValue()):null;}function header($sh,$words){for($r=1;$r<=min(25,$sh->getHighestRow());$r++){ $text=strtolower(implode(' ',$sh->rangeToArray('A'.$r.':'.$sh->getHighestColumn().$r)[0]??[]));$ok=true;foreach($words as $w)$ok=$ok&&str_contains($text,$w);if($ok)return $r;}return null;}function map($sh,$hr){$h=[];for($c=1;$c<=Coordinate::columnIndexFromString($sh->getHighestColumn());$c++)$h[$c]=strtolower(trim((string)$sh->getCellByColumnAndRow($c,$hr)->getCalculatedValue()));return $h;}
function find($h,$need){foreach($h as $i=>$v)foreach((array)$need as $n)if(str_contains($v,$n))return $i;return null;}function amount($v){return (float)preg_replace('/[^0-9.\-]/','',(string)$v);}public function advance($path,$uid=null){$book=IOFactory::load($path);$total=$ok=$bad=0;foreach($book->getWorksheetIterator() as $sh){$hr=$this->header($sh,['name']);if(!$hr)continue;$h=$this->map($sh,$hr);$log=ImportLog::create(['import_type'=>'advance','file_name'=>basename($path).' / '.$sh->getTitle(),'imported_by'=>$uid,'status'=>'completed']);for($r=$hr+1;$r<=$sh->getHighestRow();$r++){ $name=$this->val($sh,$r,$this->find($h,'name'));$amt=$this->amount($this->val($sh,$r,$this->find($h,['advance','amount'])));if(!$name&&!$amt)continue;$total++;try{$pr=$this->val($sh,$r,$this->find($h,'project'))?:$sh->getTitle();$e=$this->m->employee(['name'=>$name,'iqama_no'=>$this->val($sh,$r,$this->find($h,'iqama')),'passport_no'=>$this->val($sh,$r,$this->find($h,'passport')),'designation'=>$this->val($sh,$r,$this->find($h,['trade','designation'])),'company'=>$this->val($sh,$r,$this->find($h,['company','subcontract'])),'project'=>$pr,'doj'=>$this->val($sh,$r,$this->find($h,'doj')),'remarks'=>$this->val($sh,$r,$this->find($h,'remark')),'source_sheet'=>$sh->getTitle()]);AdvancePayment::create(['employee_id'=>$e->id,'project_id'=>$this->m->project($pr)?->id,'amount'=>$amt,'payment_date'=>now()->toDateString(),'payment_type'=>'weekly','source_sheet'=>$sh->getTitle()]);$ok++;}catch(\Throwable){$bad++;}}$log->update(['total_rows'=>$total,'success_rows'=>$ok,'failed_rows'=>$bad]);}return ['total'=>$total,'success'=>$ok,'failed'=>$bad];}
public function timesheet($path,$project,$month,$year,$uid=null){$book=IOFactory::load($path);$pid=$this->m->project($project)?->id;$total=$ok=$bad=0;foreach($book->getWorksheetIterator() as $sh){$hr=$this->header($sh,['name']);if(!$hr)continue;$h=$this->map($sh,$hr);$days=[];foreach($h as $i=>$v)if(preg_match('/^([1-9]|[12][0-9]|3[01])$/',$v,$m))$days[(int)$m[1]]=$i;AttendanceMonth::firstOrCreate(['project_id'=>$pid,'month'=>$month,'year'=>$year,'source_sheet'=>$sh->getTitle()],['source_file'=>basename($path),'imported_by'=>$uid,'imported_at'=>now()]);for($r=$hr+1;$r<=$sh->getHighestRow();$r++){ $name=$this->val($sh,$r,$this->find($h,'name'));if(!$name)continue;$total++;try{DB::transaction(function()use($sh,$r,$h,$days,$project,$pid,$month,$year,$name){$e=$this->m->employee(['name'=>$name,'iqama_no'=>$this->val($sh,$r,$this->find($h,'iqama')),'designation'=>$this->val($sh,$r,$this->find($h,['designation','trade'])),'project'=>$project,'shift'=>$this->val($sh,$r,$this->find($h,'shift')),'accommodation'=>$this->val($sh,$r,$this->find($h,'accommodation')),'remarks'=>$this->val($sh,$r,$this->find($h,'remark')),'source_sheet'=>$sh->getTitle()]);foreach($days as $d=>$c){if(!checkdate($month,$d,$year))continue;$raw=$this->val($sh,$r,$c);[$status,$hours]=$this->parse($raw);$date=Carbon::create($year,$month,$d);$extra=$status==='present'&&$date->isFriday();$type=$extra?'friday':null;AttendanceRecord::updateOrCreate(['employee_id'=>$e->id,'project_id'=>$pid,'attendance_date'=>$date->toDateString()],['month'=>$month,'year'=>$year,'status'=>$status,'hours'=>$hours,'raw_value'=>$raw,'is_extra_duty'=>$extra,'extra_duty_type'=>$type,'extra_duty_hours'=>$extra?$hours:null,'source_sheet'=>$sh->getTitle()]);if($extra&&$hours>0)ExtraDuty::updateOrCreate(['employee_id'=>$e->id,'project_id'=>$pid,'duty_date'=>$date->toDateString()],['day_type'=>'friday','hours_worked'=>$hours,'rate'=>0,'amount'=>0,'approval_status'=>'pending','remarks'=>'Imported Friday duty','source_sheet'=>$sh->getTitle()]);}});$ok++;}catch(\Throwable){$bad++;}}}return ['total'=>$total,'success'=>$ok,'failed'=>$bad];}function parse($v){$x=strtoupper(trim((string)$v));if($x==='')return ['empty',null];if(is_numeric($x))return ['present',(float)$x];return match($x){'A','ABSENT'=>['absent',null],'FRI','FRIDAY'=>['friday',null],'PH'=>['public_holiday',null],'NW'=>['not_working',null],default=>['empty',null]};}}
